// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        amount = bound(amount, 0, 1 ether);

        Receiver r = new Receiver();

        vm.deal(address(this), 1 ether);
        vm.deal(address(c), 1 ether);

        bool ok;
        try c.Command{value: amount}(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(r.lastReceived() == amount);
    }
}

contract Receiver {
    uint256 public lastReceived;
    fallback() external payable {
        lastReceived = msg.value;
    }
    receive() external payable {
        lastReceived = msg.value;
    }
}
